deleteDocument: (doc) =>
  withSb(async (c) => {
    const rm = await c.storage.from(doc.bucket).remove([doc.path]);
    if (rm.error) throw new Error(rm.error.message);
    check(await c.from('documents').delete().eq('id', doc.id));
  }),

